import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps_dict = result['data']['experiments']
# dict of exp_id -> exp_data
running = {k:v for k,v in exps_dict.items() if v.get('status') == 'RUNNING'}
print(f'=== RUNNING ({len(running)}) ===')
for eid, e in running.items():
    print(f'  {eid}: server={e.get(\"server\",\"?\")} gpu={e.get(\"gpu_id\",\"?\")}')

done = {k:v for k,v in exps_dict.items() if v.get('status') == 'DONE'}
done_sorted = sorted(done.items(), key=lambda x: x[1].get('updated_at',''), reverse=True)
print(f'\n=== Recent DONE (last 5) ===')
for eid, e in done_sorted[:5]:
    c = e.get('conclusion','?')
    m = e.get('metrics',{})
    print(f'  {eid}: {c} | greedy={m.get(\"greedy_f1\",\"?\")} oracle={m.get(\"oracle_f1\",\"?\")}')

# PREPARING/PENDING/QUEUED/ALLOCATED
for st in ['PREPARING','PENDING','QUEUED','ALLOCATED']:
    items = {k:v for k,v in exps_dict.items() if v.get('status') == st}
    if items:
        print(f'\n=== {st} ({len(items)}) ===')
        for eid in list(items.keys())[:3]:
            print(f'  {eid}')
        if len(items)>3: print(f'  ...+{len(items)-3} more')
"

